import{_ as e,o,c as t,a2 as s}from"./chunks/framework.Do1fvF3d.js";const m=JSON.parse('{"title":"Política de tratamiento de datos personales","description":"","frontmatter":{},"headers":[],"relativePath":"legal/politica-de-tratamiento.md","filePath":"legal/politica-de-tratamiento.md","lastUpdated":1791064393000}'),r={name:"legal/politica-de-tratamiento.md"};function n(i,a,d,l,c,u){return o(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="politica-de-tratamiento-de-datos-personales" tabindex="-1">Política de tratamiento de datos personales <a class="header-anchor" href="#politica-de-tratamiento-de-datos-personales" aria-label="Permalink to &quot;Política de tratamiento de datos personales&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Borrador</p><p>Este documento es un borrador pendiente de revisión legal. Los datos resaltados se completarán antes del lanzamiento.</p></div><p><strong>Versión:</strong> 2026-10-03</p><p>Esta política cumple la Ley 1581 de 2012 y el Decreto 1377 de 2013 (compilado en el Decreto 1074 de 2015) de Colombia.</p><h2 id="_1-responsable-del-tratamiento" tabindex="-1">1. Responsable del tratamiento <a class="header-anchor" href="#_1-responsable-del-tratamiento" aria-label="Permalink to &quot;1. Responsable del tratamiento&quot;">​</a></h2><ul><li><strong>Nombre:</strong> <span class="placeholder">[NOMBRE DEL RESPONSABLE]</span></li><li><strong>Identificación:</strong> <span class="placeholder">[CÉDULA O NIT]</span></li><li><strong>Domicilio:</strong> <span class="placeholder">[CIUDAD Y DIRECCIÓN]</span></li><li><strong>Correo para consultas y reclamos:</strong> <span class="placeholder">[CORREO DE CONTACTO]</span></li></ul><h2 id="_2-datos-que-tratamos-y-para-que" tabindex="-1">2. Datos que tratamos y para qué <a class="header-anchor" href="#_2-datos-que-tratamos-y-para-que" aria-label="Permalink to &quot;2. Datos que tratamos y para qué&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dato</th><th>Cómo lo guardamos</th><th>Finalidad</th></tr></thead><tbody><tr><td>Correo electrónico y contraseña</td><td>Los administra Firebase Authentication (Google); nosotros solo guardamos un identificador de la cuenta</td><td>Crear y proteger tu cuenta</td></tr><tr><td>Aceptación de términos y del aporte de agenda</td><td>Fecha y versión del texto aceptado</td><td>Demostrar tu autorización</td></tr><tr><td>Números de teléfono consultados o reportados</td><td>Solo como código (hash) con clave secreta; nunca el número</td><td>Identificar llamadas y detectar spam</td></tr><tr><td>Nombres y etiquetas de spam</td><td>Cifrados con una clave derivada de cada número</td><td>Mostrar quién llama</td></tr><tr><td>Agenda de contactos (solo si decides aportarla)</td><td>Números como código y nombres cifrados; los nombres personales (&quot;Mamá&quot;) se descartan</td><td>Identificar llamadas para la comunidad</td></tr></tbody></table><p><strong>No</strong> usamos los datos para publicidad, <strong>no</strong> los vendemos y <strong>no</strong> creamos perfiles.</p><h2 id="_3-datos-de-personas-sin-cuenta" tabindex="-1">3. Datos de personas sin cuenta <a class="header-anchor" href="#_3-datos-de-personas-sin-cuenta" aria-label="Permalink to &quot;3. Datos de personas sin cuenta&quot;">​</a></h2><p>Cuando un usuario aporta su agenda, se tratan datos de terceros (números y nombres). Para reducir el impacto sobre ellos:</p><ul><li>Nunca se guardan números de teléfono, solo códigos.</li><li>Un nombre solo se muestra si al menos 3 personas distintas lo guardaron igual.</li><li>No existe búsqueda por nombre: solo se ve un nombre si ya se tiene el número.</li><li>Cualquier persona puede pedir que se oculten los nombres de su número, sin tener cuenta (<a href="/Tranqui/guia/apelacion">cómo hacerlo</a>).</li></ul><h2 id="_4-derechos-del-titular" tabindex="-1">4. Derechos del titular <a class="header-anchor" href="#_4-derechos-del-titular" aria-label="Permalink to &quot;4. Derechos del titular&quot;">​</a></h2><p>Puedes conocer, actualizar, rectificar y suprimir tus datos, solicitar prueba de la autorización, ser informado del uso de tus datos, revocar la autorización y presentar quejas ante la Superintendencia de Industria y Comercio.</p><p>Desde la app puedes ver qué datos guardamos, dejar de aportar tu agenda y borrar tu cuenta.</p><h2 id="_5-consultas-y-reclamos" tabindex="-1">5. Consultas y reclamos <a class="header-anchor" href="#_5-consultas-y-reclamos" aria-label="Permalink to &quot;5. Consultas y reclamos&quot;">​</a></h2><p>Escribe a <span class="placeholder">[CORREO DE CONTACTO]</span>.</p><ul><li><strong>Consultas:</strong> respondemos dentro de los 10 días hábiles siguientes.</li><li><strong>Reclamos:</strong> respondemos dentro de los 15 días hábiles siguientes.</li></ul><h2 id="_6-seguridad" tabindex="-1">6. Seguridad <a class="header-anchor" href="#_6-seguridad" aria-label="Permalink to &quot;6. Seguridad&quot;">​</a></h2><p>Usamos conexiones cifradas (HTTPS), códigos con clave secreta para los números, cifrado de nombres, límites de consultas por usuario contra la extracción masiva de datos, y registros (logs) que no contienen números ni nombres.</p><h2 id="_7-transferencia-internacional" tabindex="-1">7. Transferencia internacional <a class="header-anchor" href="#_7-transferencia-internacional" aria-label="Permalink to &quot;7. Transferencia internacional&quot;">​</a></h2><p>La autenticación la presta Firebase (Google) y los servidores pueden estar fuera de Colombia, en países con un nivel adecuado de protección de datos. <span class="placeholder">[UBICACIÓN DE LOS SERVIDORES]</span></p><h2 id="_8-vigencia" tabindex="-1">8. Vigencia <a class="header-anchor" href="#_8-vigencia" aria-label="Permalink to &quot;8. Vigencia&quot;">​</a></h2><p>Esta política rige desde su publicación. Si cambia, publicaremos la nueva versión aquí y te pediremos aceptarla en la app.</p>',24)])])}const h=e(r,[["render",n]]);export{m as __pageData,h as default};
